import{_ as a,o as s,c as n,a2 as r}from"./chunks/framework.YT-FC_Xx.js";const h=JSON.parse('{"title":"基本概念","description":"","frontmatter":{},"headers":[],"relativePath":"guide/concepts.md","filePath":"guide/concepts.md","lastUpdated":1792750293000}'),d={name:"guide/concepts.md"};function e(o,t,l,i,p,g){return s(),n("div",null,[...t[0]||(t[0]=[r(`<h1 id="基本概念" tabindex="-1">基本概念 <a class="header-anchor" href="#基本概念" aria-label="Permalink to &quot;基本概念&quot;">​</a></h1><p>FLYX 由一个 <strong>面板</strong> 和装在各台服务器上的 <strong>agent</strong> 组成：面板负责配置和展示，agent 负责在服务器上执行。先弄清下面几个词，后面的文档会好读很多。</p><h2 id="整体结构" tabindex="-1">整体结构 <a class="header-anchor" href="#整体结构" aria-label="Permalink to &quot;整体结构&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端 ──► 中转服务器（前置 / IX）──► 节点（服务器上的 Xray / sing-box / Snell 入站）──► 网站</span></span>
<span class="line"><span>               ▲                          ▲</span></span>
<span class="line"><span>               └──────── agent ───────────┘</span></span>
<span class="line"><span>                           ▲</span></span>
<span class="line"><span>                     面板（Web 界面 + 后端）</span></span></code></pre></div><table tabindex="0"><thead><tr><th>名词</th><th>是什么</th><th>在面板哪里</th></tr></thead><tbody><tr><td>面板</td><td>Web 界面和后端，用 Docker 部署在一台服务器上</td><td>—</td></tr><tr><td>服务器</td><td>装了 agent、连上面板的机器，可以搭节点，也可以当中转</td><td><strong>服务器</strong> 页</td></tr><tr><td>内核</td><td>服务器上真正跑代理协议的程序：Xray、sing-box 或 Snell</td><td><strong>服务器 → 内核</strong></td></tr><tr><td>节点</td><td>客户端能连上的一个代理：自建的入站、导入的节点、订阅源里的节点</td><td><strong>节点</strong> 页</td></tr><tr><td>入站</td><td>自建的节点：内核上的一个代理服务（协议 + 端口 + 凭据）</td><td><strong>节点 → 入站</strong></td></tr><tr><td>导入的节点</td><td>不是面板搭的现成节点（脚本搭的、机场的），只用来接中转、进订阅</td><td><strong>节点 → 更多 → 导入节点</strong></td></tr><tr><td>隧道</td><td>从入口服务器到出口服务器的转发线路</td><td><strong>中转 → 隧道</strong></td></tr><tr><td>中转线路</td><td>把某条隧道接到某个节点上，客户端先连中转再到节点</td><td><strong>中转 → 线路</strong></td></tr><tr><td>转发规则</td><td>传统的端口转发：入口端口收到的流量转到目标地址</td><td><strong>规则</strong> 页</td></tr><tr><td>节点组</td><td>从节点和订阅源里挑选、筛选、改名后的一份节点列表，多个订阅可以共用</td><td><strong>订阅 → 节点组</strong></td></tr><tr><td>订阅</td><td>一个链接，包含选中节点组里的节点和它们的中转线路，客户端导入即用</td><td><strong>订阅</strong> 页</td></tr></tbody></table><h2 id="节点和中转" tabindex="-1">节点和中转 <a class="header-anchor" href="#节点和中转" aria-label="Permalink to &quot;节点和中转&quot;">​</a></h2><ul><li><strong>节点</strong>：客户端最终连到的代理，网站看到的是节点的 IP。可以在自己的服务器上搭（装内核、建入站），也可以导入现成的节点</li><li><strong>中转</strong>：客户端和节点之间的跳板，用来改善线路（比如国内前置 → IX → 海外节点），本身不跑代理协议，只转发流量</li></ul><p>一台服务器可以同时搭节点和当中转。</p><div class="tip custom-block"><p class="custom-block-title">「落地」是什么</p><p>「落地」只用在 <a href="./subscription-rules#链式代理">链式代理</a> 里，表示角色：客户端先连 <strong>中转节点</strong>，再经它连 <strong>落地节点</strong> 出去。它说的是节点在这条链里的位置，不是另一类东西。</p></div><h2 id="一条线路怎么搭起来" tabindex="-1">一条线路怎么搭起来 <a class="header-anchor" href="#一条线路怎么搭起来" aria-label="Permalink to &quot;一条线路怎么搭起来&quot;">​</a></h2><ol><li><a href="./install">安装面板</a>，在 <strong>设置</strong> 里填好“面板后端地址”</li><li><a href="./agent">安装 agent</a>：在要用的服务器上运行面板生成的安装命令</li><li><a href="./nodes">搭建节点</a>：给服务器装内核、建入站</li><li><a href="./relay">对接中转</a>（可选）：建隧道，把它接到节点上</li><li><a href="./subscription">订阅</a>：建节点组，再把节点和中转线路一起导入客户端</li></ol><p>照着做一遍见 <a href="./getting-started">快速上手</a>。</p>`,12)])])}const u=a(d,[["render",e]]);export{h as __pageData,u as default};
